const messages = { en, "pt-PT": ptPT, "pt-BR": ptBR } satisfies Record<Locale, Messages>
const locales: Locale[] = ["en", "pt-PT", "pt-BR"]
const englishKeys = new Map<string, MessageKey>(Object.entries(en).map(([key, value]) => [value, key as MessageKey]))
const [uiLocale, setUiLocale] = createSignal<Locale>("en")

function format(message: string, values?: Record<string, string | number>) {
  if (!values) return message
  return Object.entries(values).reduce((result, [key, value]) => result.replaceAll(`{${key}}`, String(value)), message)
}

export function normalizeLocale(value: unknown): Locale {
  return locales.includes(value as Locale) ? (value as Locale) : "en"
}

export function localeLabel(locale = uiLocale()) {
  if (locale === "pt-PT") return "PT-PT"
  if (locale === "pt-BR") return "PT-BR"
  return "EN"
}

export function translate(locale: Locale, key: MessageKey, values?: Record<string, string | number>) {
  return format(messages[locale][key], values)
}

export function t(key: MessageKey, values?: Record<string, string | number>) {
  return translate(uiLocale(), key, values)
}

export function tx(value: string | undefined) {
  if (value === undefined) return value
  const key = englishKeys.get(value)
  if (key) return t(key)
  const phrase = phrases[value as keyof typeof phrases]
  if (!phrase || uiLocale() === "en") return value
  return phrase[uiLocale() === "pt-PT" ? 0 : 1]
}

const I18nContext = createContext({ locale: uiLocale, setLocale: (_locale: Locale) => {}, cycle: () => {} })

export function I18nProvider(props: ParentProps) {
  const kv = useKV()
  const config = useTuiConfig()

  createEffect(() => {
    if (!kv.ready) return
    setUiLocale(normalizeLocale(kv.get("matrix_locale", config.locale)))
  })

  const setLocale = (locale: Locale) => {
    setUiLocale(locale)
    kv.set("matrix_locale", locale)
  }
  const cycle = () => setLocale(locales[(locales.indexOf(uiLocale()) + 1) % locales.length] ?? "en")
  const value = { locale: uiLocale, setLocale, cycle }

  return createComponent(I18nContext.Provider, {
    value,
    get children() {
      return props.children
    },
  })
}

export function useI18n() {
  return useContext(I18nContext)
}

export { setUiLocale, uiLocale }
